const n="/**\r\n * 沙箱功能测试页面脚本\r\n * 用于验证优化后的沙箱执行器是否正常工作\r\n */\r\n\r\n// 页面初始化\r\nconsole.log('🧪 沙箱测试页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('handleTest', function() {\r\n  console.log('✅ 基本函数注册测试通过')\r\n  return 'test result'\r\n});\r\n\r\nregisterFunction('handleContextTest', function() {\r\n  // 测试$data访问\r\n  if (typeof $data === 'function') {\r\n    console.log('✅ $data 上下文访问正常')\r\n  }\r\n\r\n  // 测试$call调用\r\n  if (typeof $call === 'function') {\r\n    console.log('✅ $call 函数调用正常')\r\n  }\r\n\r\n  return 'context test passed'\r\n});\r\n\r\nregisterFunction('handleAsyncTest', async function() {\r\n  console.log('🚀 开始异步测试...')\r\n  await new Promise(resolve => setTimeout(resolve, 100))\r\n  console.log('✅ 异步操作测试通过')\r\n  return 'async test passed'\r\n});\r\n\r\nregisterFunction('handleErrorTest', function() {\r\n  try {\r\n    // 这应该会抛出错误\r\n    throw new Error('测试错误')\r\n  } catch (error) {\r\n    console.log('✅ 错误处理测试通过:', error.message)\r\n    return 'error test passed'\r\n  }\r\n});\r\n\r\nregisterFunction('handleRenderTest', function() {\r\n  return {\r\n    render() {\r\n      return this.$createElement('div', {\r\n        style: { color: 'green', padding: '10px', border: '1px solid green' }\r\n      }, '沙箱渲染测试组件')\r\n    }\r\n  }\r\n});\r\n\r\nregisterFunction('__init__', function() {\r\n  console.log('🚀 沙箱测试页面初始化完成')\r\n});\r\nregisterFunction('handleContextTest', handleContextTest)\r\nregisterFunction('handleAsyncTest', handleAsyncTest)\r\nregisterFunction('handleErrorTest', handleErrorTest)\r\nregisterFunction('RenderTestComponent', RenderTestComponent)\r\nregisterFunction('__init__', __init__)";export{n as default};
